dashboard.definition:
{
  "title": "Training",
  "description": "Weekly activity, imported Relative Effort and confirmed custom heart-rate zones. Missing effort is unknown; no proprietary fitness or readiness score is inferred. Year grain uses snapshot history; Comparable YTD ends at the import calendar date. Empty charts mean no eligible data in the selection. Automatic selects the first available metric; invalid bookmarked IDs show an explicit unavailable state. Availability is snapshot-wide and refreshes every five minutes.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.line",
      "title": "$load_metadata:result.title$",
      "dataSources": {
        "primary": "load_chart"
      },
      "options": {
        "nullValueDisplay": "gaps",
        "yAxisTitleText": "$load_metadata:result.unit$",
        "xAxisTitleText": "Period"
      },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.table",
      "title": "Configured goal \u00b7 progress at import",
      "dataSources": {
        "primary": "table_1"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.table",
      "title": "Training details",
      "dataSources": {
        "primary": "table_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    }
  },
  "dataSources": {
    "dimensions": {
      "type": "ds.search",
      "name": "dimensions",
      "options": {
        "query": "| inputlookup training_lens_dimension_options | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "sport_options": {
      "type": "ds.chain",
      "name": "sport_options",
      "options": {
        "query": "| where dimension=\"sport\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "gear_options": {
      "type": "ds.chain",
      "name": "gear_options",
      "options": {
        "query": "| where dimension=\"gear\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "metric_options": {
      "type": "ds.search",
      "name": "metric_options",
      "options": {
        "query": "| inputlookup training_lens_metric_availability | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | where sport=$sport|s$ AND gear=$gear|s$ AND valid_count>0 AND metric_id IN (\"effort\",\"hours\",\"activities\",\"zones\") | lookup training_lens_metric_catalog metric_id OUTPUT label sort_order prerequisite | stats first(label) AS label first(sort_order) AS sort_order max(refreshed_at) AS refreshed_at BY metric_id | eval label=if(now()-refreshed_at>900,label.\" \u00b7 cache stale\",label) | append [ | makeresults | eval metric_id=\"__auto__\",label=\"Automatic / first available\",sort_order=-1 ] | sort 0 sort_order metric_id",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "load_options": {
      "type": "ds.chain",
      "name": "load_options",
      "options": {
        "query": "| where metric_id=\"__auto__\" OR metric_id IN (\"effort\",\"hours\",\"activities\",\"zones\")",
        "extend": "metric_options"
      }
    },
    "load_metadata": {
      "type": "ds.chain",
      "name": "load_metadata",
      "options": {
        "query": "| where metric_id!=\"__auto__\" AND ($load|s$=\"__auto__\" OR metric_id=$load|s$) | head 1 | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),title=label.\" (\".unit.\")\" | appendpipe [ stats count | where count=0 | eval metric_id=\"__none__\",unit=\"\",title=\"Choose an available metric \u00b7 cache pending or selection unavailable\" ] | fields metric_id title unit",
        "extend": "load_options",
        "enableSmartSources": true
      }
    },
    "load_aggregate": {
      "type": "ds.search",
      "name": "load_aggregate",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | where $load_metadata:result.metric_id|s$!=\"zones\" | append [ search index=strava sourcetype IN (training_lens:activity,training_lens:zone,training_lens:ready) earliest=0 latest=+10y | dedup event_id keepempty=true | eval candidate_epoch=if(sourcetype=\"training_lens:ready\" AND ($snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$),import_epoch,null()) | eventstats max(candidate_epoch) AS chosen_epoch | eval membership=if(sourcetype=\"training_lens:activity\" AND import_epoch=chosen_epoch AND ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1),json_object(\"local_date\",local_date,\"local_month\",local_month,\"local_week_start\",local_week_start,\"local_year\",local_year,\"comparison_month_day\",comparison_month_day,\"sport\",sport,\"gear\",gear,\"timestamp\",timestamp),null()) | eventstats values(membership) AS membership BY stream_revision_id | where sourcetype=\"training_lens:zone\" AND mvcount(membership)>0 | mvexpand membership | spath input=membership | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | where $load_metadata:result.metric_id|s$=\"zones\" ] | eval metric_id=$load_metadata:result.metric_id|s$ | eval eligible=case(metric_id=\"effort\",if(isnotnull(relative_effort),1,0),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,0),metric_id=\"activities\",if(true(),1,0),metric_id=\"zones\",if(isnotnull(seconds),1,0)),numerator=case(metric_id=\"effort\",if(isnotnull(relative_effort),relative_effort,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),moving_time_s,null()),metric_id=\"activities\",if(true(),1,null()),metric_id=\"zones\",if(isnotnull(seconds),seconds,null())),denominator=case(metric_id=\"effort\",if(isnotnull(relative_effort),1,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,null()),metric_id=\"activities\",if(true(),1,null()),metric_id=\"zones\",if(isnotnull(seconds),1,null())) | eval bucket=case($grain|s$=\"Year\",coalesce(local_year,strftime(timestamp,\"%Y\")),$grain|s$=\"Month\",coalesce(local_month,strftime(timestamp,\"%Y-%m\")),true(),coalesce(local_week_start,strftime(relative_time(timestamp,\"@w1\"),\"%Y-%m-%d\"))),series=case(metric_id=\"zones\",\"Zone \".zone,metric_id IN (\"pace\",\"speed\") AND $sport|s$=\"All\",coalesce(sport,\"Unspecified\").if($split|s$=\"Gear\",\" \u00b7 \".coalesce(gear,\"Unspecified\"),\"\"),$split|s$=\"Sport\",coalesce(sport,\"Unspecified\"),$split|s$=\"Gear\",coalesce(gear,\"Unspecified\"),true(),\"Selected activities\") | stats sum(numerator) AS numerator sum(denominator) AS denominator max(numerator) AS peak median(numerator) AS midpoint avg(numerator) AS average dc(eval(if(eligible=1,local_date,null()))) AS days sum(eligible) AS valid_count count AS total_count BY bucket series metric_id | eval value=case(metric_id=\"effort\",if(valid_count>0,numerator,null()),metric_id=\"hours\",if(valid_count>0,numerator,null()),metric_id=\"activities\",if(valid_count>0,numerator,null()),metric_id=\"zones\",if(valid_count>0,numerator,null())) | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit metric_factor imperial_factor precision | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),value=round(value*if($units|s$=\"Imperial\",imperial_factor,metric_factor),precision),coverage=if(total_count>0,100*valid_count/total_count,null()),series_label=series.\" \u00b7 \".label.\" (\".unit.\")\" | fields bucket series_label value unit coverage | sort 0 bucket series_label",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "load_chart": {
      "type": "ds.chain",
      "name": "load_chart",
      "options": {
        "query": "| xyseries bucket series_label value | appendpipe [ where $grain|s$=\"Year\" | makecontinuous bucket span=1 | eval _expanded=1 ] | where $grain|s$!=\"Year\" OR _expanded=1 | fields - _expanded",
        "extend": "load_aggregate"
      }
    },
    "goal_options": {
      "type": "ds.chain",
      "name": "goal_options",
      "options": {
        "query": "| where dimension=\"goal\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All configured goals\" ]",
        "extend": "dimensions"
      }
    },
    "table_1": {
      "type": "ds.search",
      "name": "table_1",
      "options": {
        "query": "index=strava sourcetype=training_lens:goal earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | eval goal_key=sport.\" \u00b7 \".metric.\" \u00b7 \".period | where $goal|s$=\"All\" OR goal_key=$goal|s$ | table sport metric target period period_start as_of progress_value progress_pct",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "table_2": {
      "type": "ds.search",
      "name": "table_2",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($training_details|s$=\"Weekly log\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | eval distance_m=if($quality_mode|s$=\"Validated\" AND distance_valid!=1,null(),distance_m), moving_time_s=if($quality_mode|s$=\"Validated\" AND duration_valid!=1,null(),moving_time_s) | stats count AS activities dc(local_date) AS active_days sum(moving_time_s) AS seconds sum(relative_effort) AS effort count(relative_effort) AS known_effort BY local_week_start | eval hours=round(seconds/3600,2), missing_effort=activities-known_effort | sort local_week_start | where $training_details|s$=\"Weekly log\" | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($training_details|s$=\"Effort comparison\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | stats sum(relative_effort) AS effort count AS activities count(relative_effort) AS known BY local_week_start | eval effort=if(known=0,null(),effort) | sort local_week_start | streamstats current=f window=4 avg(effort) AS preceding_recorded_weeks | fields local_week_start effort preceding_recorded_weeks | where $training_details|s$=\"Effort comparison\" ] | append [ search index=strava sourcetype=training_lens:zone [ | makeresults | eval search=if($training_details|s$=\"HR observation coverage\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND stream_revision_id!=\"\" | fields stream_revision_id | appendpipe [ stats count | where count=0 | eval stream_revision_id=\"__none__\" ] | fields stream_revision_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | dedup activity_id | stats sum(observed_s) AS observed_seconds sum(unobserved_s) AS unobserved_seconds sum(paused_s) AS paused_seconds | where $training_details|s$=\"HR observation coverage\" ] | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($training_details|s$=\"Effort coverage\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | stats count AS activities count(relative_effort) AS known_effort BY sport | eval coverage_pct=round(100*known_effort/activities,1) | where $training_details|s$=\"Effort coverage\" ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period (Year grain uses history)",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "dataSources": {
        "primary": "sport_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "gear": {
      "type": "input.dropdown",
      "title": "Gear",
      "dataSources": {
        "primary": "gear_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "gear",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "quality_mode": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "grain": {
      "type": "input.dropdown",
      "title": "Time grain",
      "options": {
        "token": "grain",
        "defaultValue": "Month",
        "items": [
          {
            "label": "Week",
            "value": "Week"
          },
          {
            "label": "Month",
            "value": "Month"
          },
          {
            "label": "Year",
            "value": "Year"
          }
        ]
      }
    },
    "history_scope": {
      "type": "input.dropdown",
      "title": "Annual scope",
      "options": {
        "token": "history_scope",
        "defaultValue": "Full years",
        "items": [
          {
            "label": "Full years",
            "value": "Full years"
          },
          {
            "label": "Comparable YTD",
            "value": "Comparable YTD"
          }
        ]
      }
    },
    "split": {
      "type": "input.dropdown",
      "title": "Group series",
      "options": {
        "token": "split",
        "defaultValue": "Sport",
        "items": [
          {
            "label": "Total",
            "value": "Total"
          },
          {
            "label": "Sport",
            "value": "Sport"
          },
          {
            "label": "Gear",
            "value": "Gear"
          }
        ]
      }
    },
    "load": {
      "type": "input.dropdown",
      "title": "Metric \u00b7 load",
      "dataSources": {
        "primary": "load_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"metric_id\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "load",
        "defaultValue": "__auto__",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "goal": {
      "type": "input.dropdown",
      "title": "Configured goal",
      "dataSources": {
        "primary": "goal_options"
      },
